#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
float happy_star(vec2 uv, float anim)
{
    uv = abs(uv);
    vec2 pos = min(uv.xy/uv.yx, anim);
    float p = (2.0 - pos.x - pos.y);
    return (2.0+p*(p*p-1.5)) / (uv.x+uv.y);      
}

void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);
     vec2 uv = ( C - .5*iResolution.xy ) / iResolution.y;
    vec3 p,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1));  
    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(0.2,0.2,1.),H(g*.1),.8)*13./e/8e3
    )
    {
        p=g*d;

        vec2 u= C;
        vec4 O2=O;
     vec2 R = iResolution.xy,
         U = .55*abs(u+u - R)/R.y - .5;
    O2/= texture(iChannel0, (U.x>U.y ? U : U.yx) + 21.2/R ); 

        a=30.;
        p=mod(p-a,a*2.)-a;
        s=3.;
        for(int i=0;i++<8;){
            p=.3-abs(p+O2.xyz);
             p.zx*=mat2(cos(iTime*1.1), sin(iTime*1.1),-sin(iTime*1.1),cos(iTime*0.1));
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=1.7+sin(iTime*.01)*3.1;
            p=abs(p)*e-
                vec3(
                    5.*3.+sin(iTime*.11),
                    120,
                    8.*5.+cos(iTime*.11)
                 )+O2.xyz;
         }
         g+=e=length(p.yzx)/s;
    }
     uv *= 2.0 * ( cos(iTime * 2.0) -2.5); // scale
    float anim = sin(iTime * 12.0) * 0.1 + 1.0;  // anim between 0.9 - 1.1 
    O*= vec4(happy_star(uv, anim) * vec3(0.35,0.2,1.15)*10., 1.0);
}
